const queryClient = new QueryClient();
const navGroups = [
  { label: 'Command', items: [{ href: '/dashboard', label: 'Overview', icon: LayoutDashboard }, { href: '/cases', label: 'Cases', icon: BriefcaseBusiness }, { href: '/documents', label: 'Documents', icon: FileText }] },
  { label: 'Integrity', items: [{ href: '/search', label: 'Search intelligence', icon: BrainCircuit }, { href: '/audit', label: 'Audit trail', icon: ClipboardList }, { href: '/security', label: 'Security center', icon: ShieldCheck }] },
  { label: 'Administration', items: [{ href: '/admin', label: 'Users & roles', icon: Users }, { href: '/settings', label: 'Prototype settings', icon: Settings }] },
];

function cn(...parts: (string | false | undefined)[]) { return parts.filter(Boolean).join(' '); }
function fmt(value?: string) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' }); }
function shortDate(value?: string) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }); }

function StatusPill({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'good' | 'warn' | 'bad' | 'neutral' }) {
  const tones = { good: 'bg-[#e5f2e9] text-[#276344] border-[#b9d9c1]', warn: 'bg-[#fff3d6] text-[#8d641d] border-[#e9ce88]', bad: 'bg-[#fbe7e4] text-[#a13a31] border-[#e8b5ae]', neutral: 'bg-secondary text-muted-foreground border-border' };
  return <span className={cn('inline-flex items-center gap-1.5 border rounded-full px-2.5 py-1 text-[11px] font-semibold tracking-wide uppercase', tones[tone])}>{children}</span>;
}
function Skeleton({ className = '' }: { className?: string }) { return <div className={cn('animate-pulse rounded-md bg-[#e8e4d9]', className)} />; }
function QueryState({ loading, error, empty, children, retry }: { loading?: boolean; error?: boolean; empty?: boolean; children: ReactNode; retry?: () => void }) {
  if (loading) return <div className="space-y-3"><Skeleton className="h-16 w-full" /><Skeleton className="h-16 w-full" /><Skeleton className="h-16 w-4/5" /></div>;
  if (error) return <div className="rounded-xl border border-[#e8b5ae] bg-[#fbe7e4] p-6 text-[#7e302b]"><div className="flex items-center gap-2 font-semibold"><Siren className="size-4" />SecureDMS could not reach the prototype API</div><p className="mt-1 text-sm opacity-80">Check the API server, then retry this view.</p>{retry && <Button onClick={retry} variant="outline" className="mt-4 border-[#c27c73] text-[#7e302b]"><RefreshCw className="size-4" />Retry</Button>}</div>;
  if (empty) return <div className="border border-dashed border-border rounded-xl p-12 text-center bg-card"><Archive className="mx-auto size-8 text-muted-foreground" /><h3 className="mt-3 font-semibold">No records in this view</h3><p className="mt-1 text-sm text-muted-foreground">Try changing the filters or add the first record.</p></div>;
  return <>{children}</>;
}
function SectionHeading({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: ReactNode }) {
  return <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between mb-6"><div>{eyebrow && <div className="mono text-[10px] uppercase tracking-[.2em] text-[#927025]">{eyebrow}</div>}<h1 className="mt-1 text-2xl sm:text-3xl font-semibold tracking-[-.04em]">{title}</h1>{detail && <p className="mt-1 text-sm text-muted-foreground">{detail}</p>}</div>{action}</div>;
}
function Metric({ label, value, note, icon: Icon, accent = false }: { label: string; value: ReactNode; note: string; icon: typeof Gauge; accent?: boolean }) {
  return <div className={accent ? 'rounded-xl border p-4 shadow-sm border-[#dcb75d] bg-[#fff8e7]' : 'rounded-xl border p-4 bg-card shadow-sm'}><div className="flex items-center justify-between"><span className="text-[11px] uppercase tracking-[.12em] text-muted-foreground">{label}</span><Icon className={accent ? 'size-4 text-[#927025]' : 'size-4 text-[#47807a]'} /></div><div className="mt-3 text-3xl font-semibold tracking-[-.06em]">{value}</div><div className="mt-2 text-xs text-muted-foreground">{note}</div></div>;
}
function Logo() { return <div className="flex items-center gap-3"><div className="relative flex size-9 items-center justify-center rounded-lg bg-[#e6b94e] text-[#17363a]"><ShieldHalf className="size-5" /><span className="absolute -bottom-1 -right-1 size-2 rounded-full bg-[#77b59c] ring-2 ring-[#17363a]" /></div><div><div className="font-semibold tracking-[-.03em]">Secure<span className="text-[#e6b94e]">DMS</span></div><div className="mono text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/60">Evidence command</div></div></div>; }

function Shell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation(); const [open, setOpen] = useState(false);
  const [session, setSession] = useState(() => { try { return JSON.parse(localStorage.getItem('securedms-session') || 'null'); } catch { return null; } });
  const signOut = () => { localStorage.removeItem('securedms-session'); setSession(null); setLocation('/'); };
  if (!session && location !== '/') return <Login onLogin={(value) => { localStorage.setItem('securedms-session', JSON.stringify(value)); setSession(value); setLocation('/dashboard'); }} />;
  if (location === '/') return <Login onLogin={(value) => { localStorage.setItem('securedms-session', JSON.stringify(value)); setSession(value); setLocation('/dashboard'); }} />;
  return <div className="grain min-h-[100dvh] bg-background"><aside className={cn('fixed inset-y-0 left-0 z-40 w-[256px] bg-sidebar text-sidebar-foreground px-5 py-6 transition-transform md:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}><div className="flex items-center justify-between"><Logo /><button className="md:hidden" onClick={() => setOpen(false)} data-testid="button-close-menu"><X className="size-5" /></button></div><div className="mt-10 space-y-7">{navGroups.map((group) => <div key={group.label}><div className="mono mb-2 px-3 text-[9px] uppercase tracking-[.22em] text-sidebar-foreground/40">{group.label}</div><nav className="space-y-1">{group.items.map((item) => { const Icon = item.icon; const active = location === item.href || location.startsWith(item.href + '/'); return <Link key={item.href} href={item.href} onClick={() => setOpen(false)} data-testid={`link-nav-${item.label.toLowerCase().replaceAll(' ', '-')}`} className={cn('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition-colors', active ? 'bg-sidebar-accent text-sidebar-foreground' : 'text-sidebar-foreground/65 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground')}><Icon className={cn('size-4', active && 'text-sidebar-primary')} /><span>{item.label}</span>{active && <ChevronRight className="ml-auto size-3 text-sidebar-primary" />}</Link>; })}</nav></div>)}</div><div className="absolute inset-x-5 bottom-5 rounded-xl border border-sidebar-border bg-sidebar-accent/50 p-3"><div className="flex items-center gap-2"><div className="flex size-8 items-center justify-center rounded-full bg-[#e6b94e] text-xs font-bold text-[#17363a]">{session?.user?.initials || 'DA'}</div><div className="min-w-0"><div className="truncate text-xs font-semibold">{session?.user?.name || 'Demo Analyst'}</div><div className="truncate text-[10px] text-sidebar-foreground/55">{session?.user?.role || 'Police officer'}</div></div><button onClick={signOut} title="Sign out" className="ml-auto text-sidebar-foreground/55 hover:text-sidebar-foreground" data-testid="button-sign-out"><ArrowUpRight className="size-4" /></button></div></div></aside><main className="min-h-[100dvh] md:pl-[256px]"><header className="sticky top-0 z-30 flex h-[70px] items-center justify-between border-b border-border bg-background/90 px-5 backdrop-blur sm:px-8"><div className="flex items-center gap-3"><button className="md:hidden" onClick={() => setOpen(true)} data-testid="button-open-menu"><Menu className="size-5" /></button><div className="hidden text-sm text-muted-foreground sm:block">Evidence command center <span className="mx-2 text-border">/</span> <span className="text-foreground">{navGroups.flatMap(x => x.items).find(x => location === x.href || location.startsWith(x.href + '/'))?.label || 'Workspace'}</span></div></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-full border border-border bg-card px-3 py-1.5 text-xs text-muted-foreground sm:flex"><span className="size-1.5 rounded-full bg-[#4f987b]" />Prototype environment</div><button className="relative rounded-md p-2 text-muted-foreground hover:bg-secondary" data-testid="button-notifications"><Bell className="size-4" /><span className="absolute right-1.5 top-1.5 size-1.5 rounded-full bg-[#d89931]" /></button><div className="flex size-8 items-center justify-center rounded-full bg-[#d9ebe2] text-xs font-bold text-[#276344]">{session?.user?.initials || 'DA'}</div></div></header><div className="mx-auto max-w-[1450px] p-5 sm:p-8">{children}</div></main></div>;
}

function Login({ onLogin }: { onLogin: (session: any) => void }) {
  const login = useLogin(); const [email, setEmail] = useState('officer@demo.gov'); const [password, setPassword] = useState('demo123'); const [error, setError] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); login.mutate({ data: { email, password } }, { onSuccess: onLogin, onError: () => setError('Use one of the prototype identities or check the API server.') }); };
  return <div className="grain flex min-h-[100dvh] bg-[#17363a] text-[#f8f2e4]"><div className="hidden w-[42%] flex-col justify-between border-r border-[#496266] p-10 lg:flex"><Logo /><div><div className="mono mb-5 text-[10px] uppercase tracking-[.25em] text-[#e6b94e]">Secure digital chain of custody</div><h1 className="max-w-md text-5xl font-semibold leading-[.96] tracking-[-.065em]">Trust the record.<br /><span className="text-[#e6b94e]">Prove the change.</span></h1><p className="mt-6 max-w-sm text-sm leading-6 text-[#c4d0cc]">A focused evidence workspace for the people who carry a case from first report to final hearing.</p></div><div className="flex items-end justify-between text-xs text-[#9db0aa]"><span>SIH 2026 • Prototype</span><span className="mono">SEC/01</span></div></div><div className="flex flex-1 items-center justify-center p-6 sm:p-12"><form onSubmit={submit} className="w-full max-w-[410px] rise"><div className="mb-10 lg:hidden"><Logo /></div><div className="mono text-[10px] uppercase tracking-[.2em] text-[#e6b94e]">Restricted workspace</div><h2 className="mt-3 text-3xl font-semibold tracking-[-.05em]">Sign in to SecureDMS</h2><p className="mt-2 text-sm text-[#b6c5bf]">Prototype access for verified case teams.</p><div className="mt-8 space-y-4"><label className="block text-sm"><span className="mb-1.5 block text-[#dce5df]">Official email</span><Input data-testid="input-email" value={email} onChange={e => setEmail(e.target.value)} className="h-11 border-[#496266] bg-[#20464a] text-[#f8f2e4] placeholder:text-[#829995]" /></label><label className="block text-sm"><span className="mb-1.5 block text-[#dce5df]">Passphrase</span><Input data-testid="input-password" type="password" value={password} onChange={e => setPassword(e.target.value)} className="h-11 border-[#496266] bg-[#20464a] text-[#f8f2e4]" /></label></div>{error && <div className="mt-4 rounded-lg border border-[#a7675f] bg-[#5c302d] p-3 text-sm text-[#ffd8d0]">{error}</div>}<Button data-testid="button-login" disabled={login.isPending} className="mt-6 h-11 w-full bg-[#e6b94e] text-[#17363a] hover:bg-[#f0ca66]">{login.isPending ? 'Verifying identity…' : <><LogIn className="size-4" />Enter command center</>}</Button><div className="mt-8 flex items-start gap-3 rounded-lg border border-[#496266] bg-[#20464a]/55 p-3 text-xs leading-5 text-[#b6c5bf]"><LockKeyhole className="mt-0.5 size-4 shrink-0 text-[#e6b94e]" />This is a SIH prototype. Credentials are demo-only and no real evidence should be uploaded.</div><div className="mt-8 text-center text-[11px] text-[#829995]">Need a demo identity? Use <button type="button" onClick={() => { setEmail('admin@demo.gov'); setPassword('admin123'); }} className="text-[#e6b94e] underline underline-offset-2" data-testid="button-demo-identity">admin@demo.gov</button></div></form></div></div>;
}

